// Public input normalization for ReceiptBatch_AddAttendees_RPA.
// Prepend this snippet to the existing "Prepare Missing Employees" JavaScript
// step. It binds the four process inputs to the globals used by that script
// and by the following attendee and guest loops. It makes no service calls and
// does not change the existing preparation or loop logic.
//
// MealAttendees, MealGuests, and GuestEmployers accept an actual array or a JSON
// array string. Null, undefined, and blank values become []. Malformed JSON, a
// non-array JSON value, and every other non-array value fail. Arrays and their
// objects are used as-is, so every field and the original order are preserved.
//
// MealNumberAttendees accepts a number or a nonblank numeric string and must be
// a nonnegative integer. A missing, blank, invalid, negative, fractional, or
// nonfinite count fails instead of being invented.
//
// GuestEmployers must have exactly one entry per MealGuests entry, in the same
// order. A length mismatch fails; the array is never padded, filtered, or
// reordered.

function mealInputText(value) {
    return value === null || value === undefined ? "" : String(value).trim();
}

function mealInputFail(message) {
    throw new Error("ReceiptBatch_AddAttendees_RPA inputs: " + message);
}

function mealInputDescribe(value) {
    if (value === null) {
        return "null";
    }
    if (value === undefined) {
        return "undefined";
    }
    if (typeof value === "string") {
        return mealInputText(value) === "" ? "a blank string" : "\"" + value + "\"";
    }
    if (Array.isArray(value)) {
        return "an array";
    }
    if (typeof value === "number" || typeof value === "boolean") {
        return String(value);
    }
    return "a value of type " + typeof value;
}

function mealInputArray(name, value) {
    if (value === null || value === undefined) {
        return [];
    }

    if (typeof value === "string") {
        if (mealInputText(value) === "") {
            return [];
        }
        try {
            value = JSON.parse(value);
        } catch (parseFailure) {
            var parseMessage = parseFailure && parseFailure.message
                ? String(parseFailure.message)
                : String(parseFailure);
            mealInputFail(name + " must be a JSON array string; " +
                "the value is not valid JSON (" + parseMessage + ").");
        }
    }

    if (!Array.isArray(value)) {
        mealInputFail(name + " must be an array or a JSON array string; " +
            "received " + mealInputDescribe(value) + ".");
    }
    return value;
}

function mealInputCount(name, value) {
    var normalized;

    if (typeof value === "number") {
        normalized = value;
    } else if (typeof value === "string" && mealInputText(value) !== "") {
        normalized = Number(mealInputText(value));
    } else {
        mealInputFail(name + " must be a nonnegative integer; received " +
            mealInputDescribe(value) + ".");
    }

    if (!isFinite(normalized) || normalized < 0 ||
        Math.floor(normalized) !== normalized) {
        mealInputFail(name + " must be a nonnegative integer; received " +
            mealInputDescribe(value) + ".");
    }
    return normalized;
}

var MealAttendees = mealInputArray(
    "MealAttendees",
    ServiceManager.getInput("MealAttendees")
);
var MealGuests = mealInputArray(
    "MealGuests",
    ServiceManager.getInput("MealGuests")
);
var MealNumberAttendees = mealInputCount(
    "MealNumberAttendees",
    ServiceManager.getInput("MealNumberAttendees")
);
var GuestEmployers = mealInputArray(
    "GuestEmployers",
    ServiceManager.getInput("GuestEmployers")
);

if (GuestEmployers.length !== MealGuests.length) {
    mealInputFail("GuestEmployers must contain one employer per guest; " +
        "received " + GuestEmployers.length + " employer(s) for " +
        MealGuests.length + " guest(s).");
}

// Meal attendee data preparation for ReceiptBatch_CreateLinesRPA.
// Runs after iExpense_attendeesEmpTableGetJS and before the native attendee
// loop. It only filters already-normalized inputs and computes the first free
// EBS row; it never calls a service or changes MealAttendees/MealNumberAttendees.

var MissingMealAttendees;
var MealAttendeeStartIndex;

var mealAttendeeEbsRawNames = Services.getResponseArray(
    iExpense_attendeesEmpTableGetJSResponse,
    "AttendiesEmpTableEmpName"
);
var mealAttendeeRowsTo = Services.getResponseValue(
    iExpense_attendeesEmpTableGetJSResponse,
    "rowsTo"
);

function mealAttendeeFail(message) {
    throw new Error("Meal attendees preparation: " + message);
}

function mealAttendeeText(value) {
    return value === null || value === undefined ? "" : String(value).trim();
}

if (mealAttendeeEbsRawNames === null || mealAttendeeEbsRawNames === undefined ||
    mealAttendeeEbsRawNames === "") {
    mealAttendeeEbsRawNames = [];
}
if (!Array.isArray(mealAttendeeEbsRawNames)) {
    mealAttendeeFail("the EBS attendee names must be an array.");
}

if (typeof mealAttendeeRowsTo === "string" &&
    mealAttendeeText(mealAttendeeRowsTo) !== "") {
    mealAttendeeRowsTo = Number(mealAttendeeRowsTo);
}
if (typeof mealAttendeeRowsTo !== "number" || !isFinite(mealAttendeeRowsTo) ||
    mealAttendeeRowsTo < 0 || Math.floor(mealAttendeeRowsTo) !== mealAttendeeRowsTo) {
    mealAttendeeFail("rowsTo must be a nonnegative integer.");
}
if (mealAttendeeRowsTo === 0) {
    if (mealAttendeeEbsRawNames.length > 1 ||
        (mealAttendeeEbsRawNames.length === 1 &&
         mealAttendeeText(mealAttendeeEbsRawNames[0]) !== "")) {
        mealAttendeeFail("rowsTo=0 does not match the returned EBS attendee rows.");
    }
} else if (mealAttendeeRowsTo !== mealAttendeeEbsRawNames.length) {
    mealAttendeeFail("rowsTo=" + mealAttendeeRowsTo + " does not match " +
        mealAttendeeEbsRawNames.length + " returned EBS attendee rows.");
}

var mealAttendeeExistingNames = {};
var mealAttendeeStartIndex = 0;
var mealAttendeeFoundBlank = false;

for (var mealAttendeeRowIndex = 0;
        mealAttendeeRowIndex < mealAttendeeEbsRawNames.length;
        mealAttendeeRowIndex++) {
    var mealAttendeeRowName = mealAttendeeEbsRawNames[mealAttendeeRowIndex];
    var mealAttendeeRowNameText = mealAttendeeText(mealAttendeeRowName);
    if (mealAttendeeRowNameText === "") {
        mealAttendeeFoundBlank = true;
        continue;
    }
    if (mealAttendeeFoundBlank) {
        mealAttendeeFail("a nonblank EBS attendee name follows a blank row at index " +
            mealAttendeeRowIndex + ".");
    }
    mealAttendeeStartIndex = mealAttendeeRowIndex + 1;
    mealAttendeeExistingNames[
        "$" + mealAttendeeRowNameText.toLowerCase()
    ] = true;
}

var mealAttendeeMissing = [];
for (var mealAttendeeIndex = 0;
        mealAttendeeIndex < MealAttendees.length;
        mealAttendeeIndex++) {
    var mealAttendee = MealAttendees[mealAttendeeIndex];
    var mealAttendeeNameKey = "$" +
        mealAttendeeText(mealAttendee.employeeName).toLowerCase();
    if (!Object.prototype.hasOwnProperty.call(
            mealAttendeeExistingNames,
            mealAttendeeNameKey)) {
        mealAttendeeMissing.push(mealAttendee);
    }
}

MissingMealAttendees = mealAttendeeMissing;
MealAttendeeStartIndex = mealAttendeeStartIndex;
